blocks.description:
Block: ESP32 DevKit

prop.noditronKind: esp32-devkit
prop.chipFamily: ESP32
prop.connectionState: disconnected
prop.lastSentSnapshot: 
prop.html: container.style.position = 'relative';
container.style.display = 'flex';
container.style.flexDirection = 'column';
container.style.boxSizing = 'border-box';
container.style.padding = '8px';
container.style.fontFamily = 'Inter, sans-serif';

let row = container.querySelector('.esp-status-row');
if (!row) {
  row = document.createElement('div');
  row.className = 'esp-status-row';
  row.style.cssText = 'display:flex;align-items:center;gap:6px;max-width:calc(100% - 26px);';
  const dot = document.createElement('span');
  dot.className = 'esp-status-dot';
  dot.style.cssText = 'width:9px;height:9px;border-radius:50%;flex:none;background:var(--border);';
  const label = document.createElement('span');
  label.className = 'esp-status-label';
  label.style.cssText = 'font-size:10px;font-weight:700;letter-spacing:.03em;color:var(--text-muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
  row.append(dot, label);

  const dirty = document.createElement('div');
  dirty.className = 'esp-dirty-row';
  dirty.style.cssText = 'font-size:9px;color:#e5b93e;margin-top:2px;';

  const gear = document.createElement('button');
  gear.type = 'button';
  gear.className = 'esp-gear';
  gear.textContent = String.fromCharCode(9881);
  gear.title = 'Configure';
  gear.style.cssText = 'position:absolute;top:4px;right:4px;width:20px;height:20px;padding:0;border-radius:5px;border:1px solid var(--border);background:none;color:var(--text-muted);font-size:11px;line-height:1;cursor:pointer;';
  gear.addEventListener('click', helpers.openDialog);

  container.append(row, dirty, gear);
}

const state = String((block.props.find((p) => p.name === 'connectionState') || {}).value || 'disconnected');
const dot = container.querySelector('.esp-status-dot');
const label = container.querySelector('.esp-status-label');
if (state === 'wifi:verified') {
  dot.style.background = '#3ecf5d';
  label.textContent = 'Logic Module running';
} else if (state === 'disconnected' || !state) {
  dot.style.background = 'var(--border)';
  label.textContent = 'Not connected';
} else if (state.indexOf('connected:') === 0) {
  dot.style.background = '#e5b93e';
  label.textContent = state.slice('connected:'.length) + ' -- bootloader';
} else if (state === 'flashed') {
  dot.style.background = '#e5b93e';
  label.textContent = 'Flashed -- not yet verified';
} else {
  dot.style.background = '#e5b93e';
  label.textContent = 'Connected -- firmware unknown';
}

const childCount = block.children ? block.children.blocks.size : 0;
const snapshot = block.children ? JSON.stringify(Array.from(block.children.blocks.values()).map((c) => ({ id: c.id, props: c.props }))) : '';
const lastSent = (block.props.find((p) => p.name === 'lastSentSnapshot') || {}).value || '';
container.querySelector('.esp-dirty-row').textContent = childCount && snapshot !== lastSent ? 'Circuit changed -- not sent' : '';
prop.dialog: container.style.fontFamily = 'Inter, sans-serif';
container.style.minWidth = '420px';

const heading = document.createElement('h3');
heading.textContent = String(block.name || 'ESP32 DEVKIT').toUpperCase();
heading.style.cssText = 'margin:0 0 14px;color:var(--success,#3ecf5d);font-size:15px;letter-spacing:.03em;';
container.appendChild(heading);

const statusEl = document.createElement('p');
statusEl.style.cssText = 'margin:0 0 12px;font-size:12px;color:var(--text-muted);';
container.appendChild(statusEl);

const logEl = document.createElement('pre');
logEl.style.cssText = 'margin:10px 0 0;padding:8px;border:1px solid var(--border);border-radius:6px;background:var(--bg-well);color:var(--text-secondary);font-family:ui-monospace,Consolas,monospace;font-size:11px;white-space:pre-wrap;word-break:break-word;max-height:140px;overflow:auto;';
logEl.textContent = String(props.connectionState || 'disconnected');
function log(line) {
  logEl.textContent += '\n' + line;
  logEl.scrollTop = logEl.scrollHeight;
}

const btnStyle = 'padding:6px 12px;border:1px solid var(--border);border-radius:6px;background:none;color:var(--text-primary);font-size:12px;cursor:pointer;';

function childSnapshot() {
  if (!block.children) return '';
  return JSON.stringify(Array.from(block.children.blocks.values()).map((c) => ({ id: c.id, props: c.props })));
}

// A different network entirely from the Web Serial link below -- this is
// HTTP to a *booted* board's own WiFi AP, only reachable once this
// computer's own WiFi is on that same network. Shown regardless of
// Web Serial support (a browser without it can still do this half).
const wifiSection = document.createElement('div');
wifiSection.style.cssText = 'margin:0 0 16px;padding-bottom:16px;border-bottom:1px solid var(--border);';
const wifiLabel = document.createElement('div');
wifiLabel.textContent = 'WIFI LINK (RUNNING FIRMWARE)';
wifiLabel.style.cssText = 'font-size:11px;font-weight:700;letter-spacing:.05em;color:var(--text-muted);margin-bottom:8px;';
wifiSection.appendChild(wifiLabel);
const wifiHint = document.createElement('p');
wifiHint.textContent = "Needs this computer's own WiFi joined to the board's network first (SSID: LOGICMOD -- no internet while connected), separate from the serial link below.";
wifiHint.style.cssText = 'margin:0 0 8px;font-size:11px;color:var(--text-muted);';
wifiSection.appendChild(wifiHint);
const wifiRow = document.createElement('div');
wifiRow.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;';
const verifyBtn = document.createElement('button');
verifyBtn.type = 'button';
verifyBtn.textContent = 'Verify over WiFi';
verifyBtn.style.cssText = btnStyle;
const sendBtn = document.createElement('button');
sendBtn.type = 'button';
sendBtn.textContent = 'Send circuit to device';
sendBtn.style.cssText = btnStyle;
sendBtn.disabled = props.connectionState !== 'wifi:verified';
wifiRow.append(verifyBtn, sendBtn);
wifiSection.appendChild(wifiRow);
const wifiStatus = document.createElement('p');
wifiStatus.style.cssText = 'margin:8px 0 0;font-size:11px;color:var(--text-muted);';
const childCount = block.children ? block.children.blocks.size : 0;
wifiStatus.textContent = childCount && childSnapshot() !== (props.lastSentSnapshot || '')
  ? 'Circuit changed since it was last sent to the device.'
  : childCount ? 'Circuit matches what was last sent.' : 'No Digital I/O blocks inside this ESP32 DevKit yet -- enter it to add some.';
wifiSection.appendChild(wifiStatus);
container.appendChild(wifiSection);

verifyBtn.addEventListener('click', async () => {
  verifyBtn.disabled = true;
  const original = verifyBtn.textContent;
  verifyBtn.textContent = 'Checking...';
  try {
    const result = await helpers.device.identify();
    if (result.reachable && result.verified) {
      helpers.setProp('connectionState', 'wifi:verified');
      log('WiFi: verified logicMod is running (' + ((result.design && result.design.blocks) || []).length + ' block(s) in its current circuit).');
      sendBtn.disabled = false;
    } else if (result.reachable) {
      helpers.setProp('connectionState', 'wifi:unknown');
      log('WiFi: reachable, but the response did not look like a logicMod circuit.');
    } else {
      log('WiFi: ' + result.error);
    }
  } finally {
    verifyBtn.disabled = false;
    verifyBtn.textContent = original;
  }
});

sendBtn.addEventListener('click', async () => {
  sendBtn.disabled = true;
  const original = sendBtn.textContent;
  sendBtn.textContent = 'Sending...';
  try {
    const children = block.children ? Array.from(block.children.blocks.values()) : [];
    const design = helpers.device.buildMinimalDesign(children);
    if (!design.blocks.length) {
      log('Nothing to send -- add a Digital I/O block inside this ESP32 DevKit with a real pin set first.');
    } else {
      await helpers.device.sendDesign(design);
      helpers.setProp('lastSentSnapshot', childSnapshot());
      wifiStatus.textContent = 'Circuit matches what was last sent.';
      log('Sent ' + design.blocks.length + ' pin(s) to the device. It reloads automatically in ~1s.');
    }
  } catch (err) {
    log('Send failed: ' + err.message);
  } finally {
    sendBtn.disabled = false;
    sendBtn.textContent = original;
  }
});

if (!helpers.serial || !helpers.serial.isSupported()) {
  statusEl.textContent = 'Web Serial is not available in this browser (use Chrome or Edge on desktop).';
  container.appendChild(logEl);
} else {
  const connectRow = document.createElement('div');
  connectRow.style.cssText = 'display:flex;gap:8px;margin-bottom:12px;';
  const connectBtn = document.createElement('button');
  connectBtn.type = 'button';
  connectBtn.textContent = 'Connect (Serial)';
  connectBtn.style.cssText = btnStyle;
  const disconnectBtn = document.createElement('button');
  disconnectBtn.type = 'button';
  disconnectBtn.textContent = 'Disconnect';
  disconnectBtn.style.cssText = btnStyle;
  disconnectBtn.disabled = true;
  connectRow.append(connectBtn, disconnectBtn);
  container.appendChild(connectRow);
  container.appendChild(statusEl);

  const filesSection = document.createElement('div');
  filesSection.style.cssText = 'display:none;';
  const filesLabel = document.createElement('div');
  filesLabel.textContent = 'FIRMWARE FILES';
  filesLabel.style.cssText = 'font-size:11px;font-weight:700;letter-spacing:.05em;color:var(--text-muted);margin:4px 0 8px;';
  filesSection.appendChild(filesLabel);
  const rows = document.createElement('div');
  filesSection.appendChild(rows);

  const presets = (helpers.serial.firmwarePresets || []).filter((p) => !props.chipFamily || p.chip === props.chipFamily);
  if (presets.length) {
    const presetLabel = document.createElement('div');
    presetLabel.textContent = 'QUICK PICK';
    presetLabel.style.cssText = 'font-size:10px;font-weight:700;letter-spacing:.05em;color:var(--text-muted);margin:2px 0 6px;';
    filesSection.appendChild(presetLabel);
    const presetRow = document.createElement('div');
    presetRow.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;margin-bottom:4px;';
    for (const preset of presets) {
      const presetBtn = document.createElement('button');
      presetBtn.type = 'button';
      presetBtn.textContent = preset.label;
      presetBtn.style.cssText = btnStyle;
      presetBtn.addEventListener('click', async () => {
        presetBtn.disabled = true;
        const original = presetBtn.textContent;
        presetBtn.textContent = 'Fetching…';
        try {
          const bytes = await helpers.serial.fetchPresetBytes(preset);
          addPresetRow(preset, bytes);
          log('Fetched ' + preset.label + ' (' + bytes.length + ' bytes).');
        } catch (err) {
          log('Could not fetch ' + preset.label + ': ' + err.message);
        } finally {
          presetBtn.disabled = false;
          presetBtn.textContent = original;
        }
      });
      presetRow.appendChild(presetBtn);
    }
    filesSection.appendChild(presetRow);
    const presetHint = document.createElement('p');
    presetHint.textContent = 'Fetched from noditron itself (private) using the GitHub token set in the library dialog.';
    presetHint.style.cssText = 'margin:0 0 10px;font-size:10px;color:var(--text-muted);';
    filesSection.appendChild(presetHint);
  }

  const addRowBtn = document.createElement('button');
  addRowBtn.type = 'button';
  addRowBtn.textContent = '+ Add file';
  addRowBtn.style.cssText = btnStyle;
  filesSection.appendChild(addRowBtn);

  const eraseRow = document.createElement('label');
  eraseRow.style.cssText = 'display:flex;align-items:center;gap:8px;margin:12px 0;cursor:pointer;font-size:12px;';
  const eraseCheckbox = document.createElement('input');
  eraseCheckbox.type = 'checkbox';
  eraseCheckbox.checked = true;
  eraseRow.append(eraseCheckbox, document.createTextNode('Erase flash before writing (recommended for a blank board)'));
  filesSection.appendChild(eraseRow);

  const progressEl = document.createElement('div');
  progressEl.style.cssText = 'margin:8px 0;font-size:12px;color:var(--text-muted);';
  filesSection.appendChild(progressEl);

  const flashBtn = document.createElement('button');
  flashBtn.type = 'button';
  flashBtn.textContent = 'Flash';
  flashBtn.style.cssText = 'padding:6px 14px;border:1px solid var(--success,#3ecf5d);border-radius:6px;background:var(--success,#3ecf5d);color:#06210f;font-size:12px;font-weight:600;cursor:pointer;';
  filesSection.appendChild(flashBtn);

  container.appendChild(filesSection);
  container.appendChild(logEl);

  let bootloaderOffset = null;

  function addFileRow() {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:8px;margin-bottom:6px;';
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = '.bin';
    fileInput.style.cssText = 'flex:1;font-size:11px;min-width:0;';
    const addrInput = document.createElement('input');
    addrInput.type = 'text';
    addrInput.style.cssText = 'width:90px;flex:none;padding:4px 6px;background:none;border:1px solid var(--border);border-radius:6px;color:var(--text-primary);font-size:12px;font-family:ui-monospace,monospace;box-sizing:border-box;';
    addrInput.value = '0x10000';
    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.textContent = String.fromCharCode(215);
    removeBtn.style.cssText = 'width:22px;height:22px;flex:none;padding:0;border:1px solid var(--border);border-radius:6px;background:none;color:var(--text-muted);cursor:pointer;';
    removeBtn.addEventListener('click', () => row.remove());
    fileInput.addEventListener('change', () => {
      const f = fileInput.files[0];
      if (f) addrInput.value = '0x' + helpers.serial.guessAddress(f.name, bootloaderOffset).toString(16);
    });
    row.append(fileInput, addrInput, removeBtn);
    rows.appendChild(row);
  }

  function addPresetRow(preset, bytes) {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:8px;margin-bottom:6px;';
    row.presetBytes = bytes;
    row.presetName = preset.path.split('/').pop();
    const nameEl = document.createElement('div');
    nameEl.textContent = preset.label + ' (' + bytes.length.toLocaleString() + ' bytes)';
    nameEl.style.cssText = 'flex:1;font-size:12px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
    const addrInput = document.createElement('input');
    addrInput.type = 'text';
    addrInput.style.cssText = 'width:90px;flex:none;padding:4px 6px;background:none;border:1px solid var(--border);border-radius:6px;color:var(--text-primary);font-size:12px;font-family:ui-monospace,monospace;box-sizing:border-box;';
    addrInput.value = '0x' + preset.address.toString(16);
    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.textContent = String.fromCharCode(215);
    removeBtn.style.cssText = 'width:22px;height:22px;flex:none;padding:0;border:1px solid var(--border);border-radius:6px;background:none;color:var(--text-muted);cursor:pointer;';
    removeBtn.addEventListener('click', () => row.remove());
    row.append(nameEl, addrInput, removeBtn);
    rows.appendChild(row);
  }

  addFileRow();

  const existing = helpers.serial.getSession();
  statusEl.textContent = existing && existing.chipName
    ? 'Connected to ' + existing.chipName + '.'
    : 'Not connected. This board has no known firmware yet.';
  if (existing && existing.chipName) {
    bootloaderOffset = existing.bootloaderOffset;
    disconnectBtn.disabled = false;
    connectBtn.disabled = true;
    filesSection.style.display = '';
  }

  connectBtn.addEventListener('click', async () => {
    connectBtn.disabled = true;
    try {
      await helpers.serial.connect(log);
      statusEl.textContent = 'Connected -- detecting chip...';
      log('Serial port opened.');
      const detected = await helpers.serial.detectChip(log);
      bootloaderOffset = detected.bootloaderOffset;
      statusEl.textContent = 'Connected to ' + detected.chipName + '.';
      log('Detected ' + detected.chipName + ' (bootloader @ 0x' + detected.bootloaderOffset.toString(16) + ').');
      disconnectBtn.disabled = false;
      filesSection.style.display = '';
      helpers.setProp('connectionState', 'connected:' + detected.chipName);
    } catch (err) {
      statusEl.textContent = 'Connect failed: ' + err.message;
      connectBtn.disabled = false;
    }
  });

  disconnectBtn.addEventListener('click', async () => {
    await helpers.serial.disconnect();
    statusEl.textContent = 'Disconnected.';
    connectBtn.disabled = false;
    disconnectBtn.disabled = true;
    filesSection.style.display = 'none';
    helpers.setProp('connectionState', 'disconnected');
  });

  addRowBtn.addEventListener('click', () => addFileRow());

  flashBtn.addEventListener('click', async () => {
    const files = [];
    for (const row of rows.children) {
      const addrInput = row.querySelector('input[type=text]');
      const address = parseInt(addrInput.value, 16) || 0;
      if (row.presetBytes) {
        files.push({ name: row.presetName, bytes: row.presetBytes, address });
        continue;
      }
      const fileInput = row.querySelector('input[type=file]');
      const file = fileInput && fileInput.files[0];
      if (!file) continue;
      files.push({ name: file.name, file, address });
    }
    if (!files.length) { log('Pick at least one .bin file first.'); return; }
    flashBtn.disabled = true;
    try {
      await helpers.serial.flash(
        files,
        eraseCheckbox.checked,
        (fileIndex, written, total) => {
          progressEl.textContent = 'File ' + (fileIndex + 1) + ': ' + Math.round((written / total) * 100) + '%';
        },
        log,
      );
      statusEl.textContent = 'Flashed. Board rebooted -- reconnect to re-detect firmware.';
      helpers.setProp('connectionState', 'flashed');
    } catch (err) {
      log('Flash failed: ' + err.message);
    } finally {
      flashBtn.disabled = false;
    }
  });
}

